parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
staticData.auditLog = staticData.auditLog || [];
const j = $json;
const d = j.aiDecision || {};

const event = {
  event_id: 'EVT-' + j.correlationId,
  timestamp: new Date().toISOString(),
  correlation_id: j.correlationId,
  actor_type: j.actorType,
  actor_reference: j.customerId || j.driverId || j.phone,
  delivery_reference: j.lastOrderReference || null,
  locker_reference: null,
  action: j.gate ? j.gate.action : d.action,
  authorization_result: j.gate ? (j.gate.allowed ? 'ALLOWED' : j.gate.denyReason) : 'N/A',
  result: j.toolErrorCategory || 'N/A',
  failure_code: (j.toolResult && j.toolResult.success === false) ? j.toolErrorCategory : null,
  source: 'n8n-llbox-workflow',
  workflow_version: j.workflowVersion,
  knowledge_version: j.knowledgeVersion
};

// Keep only the last 500 in-memory to bound memory growth. Production should
// send every event to the LLBox backend audit endpoint (see HTTP node above).
staticData.auditLog.push(event);
if (staticData.auditLog.length > 500) staticData.auditLog.shift();

return [{ json: { ok: true, event } }];

// Independent second check: OUR backend record for this phone number must
// agree with what ElevenLabs asserted, before any delivery/locker detail
// is fetched or sent. Neither source is trusted alone.
const j = $('Voice Dedup + Rate Limit').item.json;
const lookup = $json.data || $json || {};
const contact = lookup.contact || {};

let backendActorType = 'unknown';
if (contact.driverVerified === true && contact.driverId) backendActorType = 'driver';
else if (contact.customerVerified === true && contact.customerId) backendActorType = 'customer';

const backendReference = backendActorType === 'driver' ? contact.driverId
  : backendActorType === 'customer' ? contact.customerId : null;

const ownershipVerified =
  backendActorType === j.verified_actor_type &&
  backendReference &&
  String(backendReference) === String(j.verified_reference);

return [{ json: { ...j, ownershipVerified, backendActorType, backendReference } }];

const staticData = $getWorkflowStaticData('global');
staticData.vaProcessed = staticData.vaProcessed || {};
staticData.vaRateWindows = staticData.vaRateWindows || {};
const cfg = $('Config VA').item.json;
const j = $json;
const now = Date.now();

const dedupKey = j.conversation_id + ':' + j.message_type;
const TTL_MS = 6 * 60 * 60 * 1000;
for (const [k, ts] of Object.entries(staticData.vaProcessed)) {
  if (now - ts > TTL_MS) delete staticData.vaProcessed[k];
}
const duplicate = Boolean(staticData.vaProcessed[dedupKey]);
if (!duplicate) staticData.vaProcessed[dedupKey] = now;

const limit = parseInt(cfg.rateLimitMessagesPerMinute || '5', 10);
const windowMs = 60 * 1000;
const arr = (staticData.vaRateWindows[j.caller_phone] || []).filter(ts => now - ts < windowMs);
arr.push(now);
staticData.vaRateWindows[j.caller_phone] = arr;
const rateLimited = arr.length > limit;

return [{ json: { ...j, duplicate, rateLimited } }];

const j = $json;
const backend = $('Config VA').item.json.backendUrl;

const MAP = {
  delivery_location:  { implemented: false, method: 'POST', path: '/api/tools/get-locker-location' },
  delivery_details:   { implemented: false, method: 'POST', path: '/api/tools/get-delivery-details' },
  collection_details: { implemented: false, method: 'POST', path: '/api/tools/get-collection-status' }
};
// get_customer_locker's existing confirmed endpoint doubles as a fallback for delivery_location.
const FALLBACK = { implemented: true, method: 'POST', path: '/api/tools/find-customer' };

const entry = MAP[j.message_type];
const useFallback = j.message_type === 'delivery_location' && !entry.implemented;
const chosen = useFallback ? FALLBACK : entry;

const body = {
  correlationId: j.correlationId,
  actorType: j.verified_actor_type,
  reference: j.verified_reference,
  orderReference: j.order_reference || null,
  whatsappPhone: '+' + String(j.caller_phone).replace(/^\+/, '')
};

return [{ json: { ...j, toolImplemented: chosen.implemented, toolUrl: backend + chosen.path,
  toolMethod: chosen.method, toolBody: JSON.stringify(body), usedFallback: useFallback } }];

const j = $json;
const TEMPLATES = {
  delivery_summary: 'Hi, here is a summary of your delivery as discussed on the call. Our team will follow up with any live status via this chat. / مرحباً، هذا ملخص لشحنتك كما تمت مناقشته في المكالمة.',
  support_confirmation: 'Hi, this confirms your support request from the call just now. A support agent will follow up here or by phone. / مرحباً، هذا تأكيد لطلب الدعم الخاص بك، سيتم التواصل معك قريباً.',
  general_info: 'Hi, thanks for calling LLBox. Let us know here on WhatsApp if you need anything else. / مرحباً، شكراً لتواصلك مع LLBox.'
};
let text = TEMPLATES[j.message_type];
if (j.message_type === 'custom') text = String(j.custom_text || '').trim();
return [{ json: { ...j, outboundText: text, ownershipVerified: true } }];

const staticData = $getWorkflowStaticData('global');
staticData.auditLog = staticData.auditLog || [];
const j = $json;
staticData.auditLog.push({
  event_id: 'EVT-' + j.correlationId,
  timestamp: new Date().toISOString(),
  correlation_id: j.correlationId,
  actor_type: 'voice_caller:' + (j.verified_actor_type || 'unverified'),
  actor_reference: j.verified_reference || j.caller_phone,
  action: 'voice_send_whatsapp:' + j.message_type,
  authorization_result: j.ownershipVerified === false ? 'DENIED' : 'ALLOWED',
  result: (j.error ? 'SYSTEM_UNAVAILABLE' : 'SUCCESS'),
  source: 'elevenlabs-voice-agent',
  metadata: { conversation_id: j.conversation_id, order_reference: j.order_reference || null }
});
return [{ json: { success: !j.error, correlationId: j.correlationId } }];

const j = $json;
const ALLOWED_TYPES = ['delivery_location', 'delivery_details', 'collection_details',
  'delivery_summary', 'support_confirmation', 'general_info', 'custom'];
const DYNAMIC_TYPES = ['delivery_location', 'delivery_details', 'collection_details'];
const ALLOWED_ACTORS = ['customer', 'driver'];

const errors = [];
if (!j.caller_phone || typeof j.caller_phone !== 'string') errors.push('caller_phone_required');
if (!j.conversation_id) errors.push('conversation_id_required');
if (!ALLOWED_TYPES.includes(j.message_type)) errors.push('invalid_message_type');

if (DYNAMIC_TYPES.includes(j.message_type)) {
  if (!ALLOWED_ACTORS.includes(j.verified_actor_type)) errors.push('verified_actor_type_required');
  if (!j.verified_reference) errors.push('verified_reference_required');
}

if (j.message_type === 'custom') {
  const t = String(j.custom_text || '');
  if (!t.trim()) errors.push('custom_text_required');
  if (t.length > 300) errors.push('custom_text_too_long');
  // Basic guard: never relay something that looks like a code/OTP/credential.
  if (/\b(otp|code|password|pin)\b.{0,15}\b\d{4,8}\b/i.test(t) || /\b\d{4,8}\b.{0,15}\b(otp|code|password|pin)\b/i.test(t)) {
    errors.push('custom_text_contains_sensitive_pattern');
  }
}

const correlationId = 'LLB-VA-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.random().toString(36).slice(2,10).toUpperCase();

return [{ json: { ...j, valid: errors.length === 0, errors, correlationId,
  isDynamic: DYNAMIC_TYPES.includes(j.message_type) } }];

const headers = $('ElevenLabs Tool Webhook').item.json.headers || {};
const provided = String(headers['x-llbox-tool-secret'] || headers['X-LLBox-Tool-Secret'] || '');
let expected = '';
try {
  expected = String(($('Config VA').first().json.elevenLabsToolSecret || $('Config').first().json.elevenLabsToolSecret || '') || '');
} catch (e) { expected = ''; }
const authorized = !expected || provided === expected;
const body = $('ElevenLabs Tool Webhook').item.json.body || {};
return [{ json: { authorized, ...body } }];

const j = $json;
const res = j.toolResult || j;
const data = res.data || {};

let text;
if (res.success === false && res.success !== undefined) {
  text = "Hi, I could not verify those details right now. Our support team will follow up on this chat. / مرحباً، لم أتمكن من التحقق من التفاصيل حالياً، سيتابع معك الدعم.";
} else if (j.message_type === 'delivery_location') {
  text = data.userFound
    ? `Hi, your locker location: ${data.locker || data.address || ''}.`
    : "Hi, I could not confirm a locker location for this account yet.";
} else if (j.message_type === 'delivery_details') {
  text = `Hi, here are your delivery details: ${data.summary || data.status || 'please see the attached details in this chat.'}`;
} else if (j.message_type === 'collection_details') {
  text = `Hi, collection details: ${data.summary || data.status || 'please see this chat for the latest status.'}`;
} else {
  text = "Hi, here is the information you requested on the call.";
}

return [{ json: { ...j, outboundText: text } }];

return [{ json: { ...$json,
  outboundText: "Hi, I couldn't pull those details automatically yet — our support team will follow up with you shortly on this chat. / مرحباً، لم أتمكن من جلب التفاصيل تلقائياً، سيتابع معك فريق الدعم قريباً.",
  needsEscalation: true } }];

const base = $('Rate Limit Check').item.json;
let messageText = base.messageText || base.text || '';
let transcribedText = '';
let imageAnalysis = '';
let documentResult = '';
let inputType = base.inputType || base.messageType || 'text';

function nodeJson(name) {
  try { return $(name).item.json || {}; } catch (e) { return {}; }
}
function errorText(obj) {
  if (!obj || obj.error == null) return '';
  const e = obj.error;
  if (typeof e === 'string') return e;
  return String(e.message || e.description || JSON.stringify(e)).slice(0, 400);
}
function ocrText(obj) {
  return String(
    obj.choices?.[0]?.message?.content ||
    obj.output_text ||
    obj.output?.[0]?.content?.[0]?.text ||
    obj.text ||
    obj.transcript ||
    ''
  ).trim();
}

const current = $json || {};
const getUrlJson = nodeJson('Get WhatsApp Media URL');
const downloadJson = nodeJson('Download Media');
const visionJson = nodeJson('Analyze Image (Vision)');
const documentJson = nodeJson('Analyze Document');
const whisperJson = nodeJson('Transcribe Audio (Whisper)');

if (inputType === 'audio') {
  transcribedText = ocrText(current) || ocrText(whisperJson);
  messageText = transcribedText || messageText;
}
if (inputType === 'image') {
  imageAnalysis = ocrText(current) || ocrText(visionJson);
}
if (inputType === 'document') {
  const vision = ocrText(current) || ocrText(documentJson) || ocrText(visionJson);
  const caption = base.caption || base.text || '';
  documentResult = vision || (caption ? ('Document caption: ' + caption) : '');
  imageAnalysis = imageAnalysis || vision;
}

const ocrContent = [imageAnalysis, documentResult, transcribedText]
  .filter((s) => s && !/^Document caption:/i.test(s))
  .join('\n')
  .trim();

let mediaReadFailed = false;
let mediaReadErrorReason = '';
if (errorText(getUrlJson)) {
  mediaReadFailed = true;
  mediaReadErrorReason = 'media_fetch_failed';
} else if (errorText(downloadJson)) {
  mediaReadFailed = true;
  mediaReadErrorReason = 'download_failed';
} else if (inputType === 'image' && (errorText(current) || errorText(visionJson))) {
  mediaReadFailed = true;
  mediaReadErrorReason = 'vision_api_error';
} else if (inputType === 'document' && (errorText(current) || errorText(documentJson))) {
  mediaReadFailed = true;
  mediaReadErrorReason = 'vision_api_error';
} else if (inputType === 'audio' && (errorText(current) || errorText(whisperJson))) {
  mediaReadFailed = true;
  mediaReadErrorReason = 'vision_api_error';
} else if (['image', 'document', 'audio'].includes(inputType) && !ocrContent) {
  mediaReadFailed = true;
  mediaReadErrorReason = 'empty_response';
}

if (mediaReadFailed) {
  const staticData = $getWorkflowStaticData('global');
  staticData.mediaFailures = staticData.mediaFailures || {};
  const phone = String(base.phone || '');
  const arr = Array.isArray(staticData.mediaFailures[phone]) ? staticData.mediaFailures[phone] : [];
  arr.push({
    reason: mediaReadErrorReason,
    at: Date.now(),
    ts: new Date().toISOString(),
    correlationId: base.correlationId || '',
    phone,
    inputType
  });
  staticData.mediaFailures[phone] = arr.slice(-20);
}

// Combined text for order extraction + AI (caption fallback still included)
const mediaBlob = [imageAnalysis, documentResult, transcribedText].filter(Boolean).join('\n');
const combinedText = [messageText, mediaBlob].filter(Boolean).join('\n').trim();

return [{ json: {
  ...base,
  inputType,
  messageText: combinedText || messageText,
  text: combinedText || messageText,
  transcribedText,
  imageAnalysis,
  documentResult,
  mediaBlob,
  mediaReadFailed,
  mediaReadErrorReason,
  reply_mode: inputType === 'audio' ? 'voice' : (base.reply_mode || 'text')
} }];

const j = $json;
return [{ json: {
  ...j,
  inputType: 'text',
  messageText: j.text || j.messageText || '',
  text: j.text || j.messageText || '',
  transcribedText: '',
  imageAnalysis: '',
  documentResult: '',
  mediaBlob: '',
  reply_mode: 'text'
} }];

const j = $json;
return [{ json: {
  ...j,
  inputType: j.inputType || 'unsupported',
